public final class FitxersText {

    public static void mostraInfoFitxer(String ruta) {

        // Declarem una ruta relativa al fitxer
        Path ruta_relativa = Path.of(ruta);
        System.out.println(ruta_relativa.toAbsolutePath());

        System.out.println("La ruta existeix? " + Files.exists(ruta_relativa));
        System.out.println("És un fitxer regular?" + Files.isRegularFile(ruta_relativa));
        System.out.println("És una ruta ? " + Files.isDirectory(ruta_relativa));
        System.out.println("Es pot llegir? " + Files.isReadable(ruta_relativa));
        try {
            System.out.println("Grandària del fitxer: " + Files.size(ruta_relativa));
        } catch (IOException e) {
            // Mostrem el missatge d'errot
            System.out.println(e.getMessage());
        }

    }

    public static void operacions() {
        // Definim un path a una carpeta "dades/copia" (que no existeix)
        Path carpeta = Path.of("dades", "copia");
        try {
            // Creem el directori definit pel path
            Files.createDirectories(carpeta);

            // Defniim un path al fitxer entrants.json
            Path origen = Path.of("dades", "entrants.json");
            // Amb resolve creem una nova ruta "filla" (a partir d'una altra)
            // En aquest cas, la creem a partir del path definit en carpeta
            Path copia = carpeta.resolve("entrants.json"); // (3)!

            // I fem la còpia, del path "origen" al path "copia"
            // Amb REPLACE_EXISTING directament sobreesrivim el fitxer si existeix
            Files.copy(origen, copia, StandardCopyOption.REPLACE_EXISTING);

            // Creem un nou path dins de carpeta
            Path nouNom = carpeta.resolve("entrants-backup.json");
            // Canviem de nom la còpia
            Files.move(copia, nouNom, StandardCopyOption.REPLACE_EXISTING);
            // I finalment l'esborrem (delefeIfExists comprova si existeix per esborra-lo)
            Files.deleteIfExists(nouNom);
        } catch (IOException e) {

            // Si es produeix una excepció, mostrem el missatge
            System.out.println("Excepció: " + e.getMessage());
        }

    }

    public static void recorreCarpeta() {
        // Definim el path relatiu a la carpeta
        Path dades = Path.of("dades");

        // Mostrem la ruta absoluta
        System.out.println("Ruta al fitxer: " + dades.toAbsolutePath());

        if (!Files.exists(dades)) {
            return;
        }

        // Com que l'accés als fitxers ens el proporciona el sistema operatiu
        // hem d'utilitzar una estructura try-with-resources

        // Files.list ens retorna "un Stream de Paths" (flux continu)
        try (Stream<Path> entrades = Files.list(dades)) {
            // Aquest stream es port filtrar, ordenar i recórrer així
            // (Com que un stream només es pot consumir una vegada, "encadenem" operacions)
            entrades
                    .filter(Files::isRegularFile) // Referència al mètode Files.isRegularFile
                    .sorted()
                    .forEach(System.out::println);
        } catch (IOException e) {
            System.out.println("Excepció d'Entrada i Eixida: " + e.getMessage());
        }

        // Per fer un recorregut recursiu podem utilitzar `Files.walk()`, en lloc de
        // list:

        try (Stream<Path> entrades = Files.walk(dades)) {
            entrades
                    // Ara, a filtes, li passem una lambda, per filtrar els fitxes json
                    .filter(path -> path.toString().endsWith(".json"))
                    .forEach(System.out::println);
        }

        catch (IOException e) {
            System.out.println("Excepció d'Entrada i Eixida: " + e.getMessage());
        }

    }

    public static void exercici_1(String ruta) {
        // 1. La ruta absoluta i normalitzada.
        // Definim el path relatiu a la carpeta
        Path dades = Path.of(ruta);

        // Mostrem la ruta normalitzada
        System.out.println("Ruta al fitxer: " + dades.normalize());

        // Mostrem la ruta absoluta
        System.out.println("Ruta al fitxer: " + dades.toAbsolutePath());

        // 2. Si existeix i si és un fitxer o un directori
        System.out.println("Existeix la ruta ? " + Files.exists(dades));

        if (Files.exists(dades)) {
            // Si el fitxer existeix
            // 3. Si és un directori, els fitxers que conté ordenats per nom.
            if (Files.isDirectory(dades)) {
                try (Stream<Path> entrades = Files.list(dades)) {
                    entrades
                            .filter(Files::isRegularFile)
                            .sorted()
                            .forEach(System.out::println);
                } catch (IOException e) {
                    System.out.println("Excepció d'Entrada i Eixida: " + e.getMessage());
                }

            } else if (Files.isRegularFile(dades)) {
                try {
                    System.out.println("És un fitxer i ocupa: " + Files.size(dades));
                } catch (IOException e) {
                    System.out.println("Error d'Entrada/Eixida: " + e.getMessage());
                }
            } else {
                // Aquest cas serà més estrant, però no el descartem
                System.out.println("El path existeix, però no és un directori ni un fitxer regular");
            }

        }

    }

    public static void exemple4() {
        Path origen = Path.of("dades", "acd.png");
        Path destinacio = Path.of("dades", "copia.png");

        try (InputStream entrada = Files.newInputStream(origen);
                OutputStream eixida = Files.newOutputStream(destinacio)) {

            // Opció A: amb transferTo
            // entrada.transferTo(eixida); // Així ens estalviem el bucle

            // Opció B: copiat byte a byte manualment
            byte[] buffer = new byte[8192];
            int llegits;

            while ((llegits = entrada.read(buffer)) != -1) { // Si torna -1 és que ja no li queda per llegit
                eixida.write(buffer, 0, llegits); // Abans de retornar -1, ens torna la quantitat que ha llegit
            }
        } catch (IOException e) {
            System.out.println("Excepció: " + e.getMessage());
        }

    }

    public static void exemple5() {
        // Spin off de PSP...

        // Creem el path al fitxer d'eixida
        Path destinacio = Path.of("dades", "ping.txt");

        // Definim un objecte ProcessBuilder (per crear processos)
        ProcessBuilder pb = new ProcessBuilder(
                "ping", "-c", "4", "ieseljust.com");

        // Combina l'eixida d'error amb l'eixida estàndard (stderr => stout)
        pb.redirectErrorStream(true);

        try {

            // Llancem el procés
            Process proces = pb.start();

            try ( // try-with-resources!
                  // Obtenim un InputStream del procés (l'eixida del procés)
                    InputStream entrada = proces.getInputStream();
                    // L'stream d'eixida serà el fitxer
                    OutputStream eixida = Files.newOutputStream(
                            destinacio,
                            // crea el fitxer si no existeix. Si ja existeix, l’obri sense fallar.
                            StandardOpenOption.CREATE, // Podem fer ús de .APPEND en lloc de .CREATE per afegir el
                                                       // contingut al final
                            // si el fitxer ja existeix, elimina el seu contingut i el deixa buit abans
                            StandardOpenOption.TRUNCATE_EXISTING)) {
                // Cos del try-with-resources
                entrada.transferTo(eixida);
            }

            // Hem d'esperar que acabe el procés
            int codiEixida = proces.waitFor();
            System.out.println("El procés ha acabat amb el codi: " + codiEixida);

        } catch (IOException e) {
            System.out.println("Error d'entrada/eixida: " + e.getMessage());

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println("L'espera del procés ha sigut interrompuda.");
        }

    }

    // Exemple 6. Còpia amb caràcters
    public static void exemple6() {
        Path ruta = Path.of("dades", "entrants.json");
        Path ruta_copia = Path.of("dades", "entrants_copia.json");

        // try-with-resources
        try (
                BufferedReader lector = Files.newBufferedReader(ruta, StandardCharsets.UTF_8);
                BufferedWriter escriptor = Files.newBufferedWriter(
                        ruta_copia,
                        StandardCharsets.UTF_8,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING)) {
            String linia;
            while ((linia = lector.readLine()) != null) {
                // Mostrem la línia per pantalla
                System.out.println(linia);
                escriptor.write(linia);
                escriptor.newLine();
            }
        } catch (IOException e) {
            System.out.println("Excepció E/E: " + e.getMessage());
        }
    }

    // Exemple 7. Eixida d'un procés i escriptura a fitxer fent ús de decoradors
    public static void exemple7() {

        Path destinacio = Path.of("dades", "ping_2.txt");

        ProcessBuilder pb = new ProcessBuilder(
                "ping", "-c", "4", "ieseljust.com");

        // Redirigim stderr cap a stdout
        pb.redirectErrorStream(true);

        try {
            Process proces = pb.start();

            try (
                    // Cadena d'entrada: bytes → caràcters → línies
                    InputStream isBytes = proces.getInputStream();

                    InputStreamReader isrCaracters = new InputStreamReader(
                            isBytes,
                            StandardCharsets.UTF_8);

                    BufferedReader brLinies = new BufferedReader(isrCaracters);

                    // Cadena d'eixida: línies/caràcters → bytes → fitxer
                    OutputStream osBytes = Files.newOutputStream(
                            destinacio,
                            StandardOpenOption.CREATE,
                            StandardOpenOption.TRUNCATE_EXISTING);

                    OutputStreamWriter oswCaracters = new OutputStreamWriter(
                            osBytes,
                            StandardCharsets.UTF_8);

                    BufferedWriter bwLinies = new BufferedWriter(oswCaracters)) {
                String linia;

                while ((linia = brLinies.readLine()) != null) {
                    // Mostrem la línia per pantalla
                    System.out.println(linia);

                    // I també l'escrivim al fitxer
                    bwLinies.write(linia);
                    bwLinies.newLine();
                }
            }

            int codiEixida = proces.waitFor();

            System.out.println(
                    "El procés ha acabat amb el codi: " + codiEixida);

        } catch (IOException e) {
            System.out.println(
                    "Error d'entrada/eixida: " + e.getMessage());

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println(
                    "L'espera del procés ha sigut interrompuda.");
        }
    }

    public static void exemple8() throws IOException {
        // lectura i escri

        // Definim la ruta al fitxer
        Path ruta = Path.of("dades", "entrants.json");

        // Part 1: Llegim i escrivim el fitxer tot d'una

        // Llegim el fitxer t'una, com un String
        String text = Files.readString(ruta, StandardCharsets.UTF_8);

        // I l'escrivim tot d'una, amb el text a majúscules
        Files.writeString(ruta, text.toUpperCase(), StandardCharsets.UTF_8);

        // Part 2: També podem llegir tot d'una el fitxer, però
        // obtindre ina llista amb les línies
        List<String> linies = Files.readAllLines(ruta, StandardCharsets.UTF_8);
        linies.forEach(linia -> System.out.println(linia));

        // Part 3: Lectura línia a línia d'un fitxer
        // Obtenim l'stream amb les línies del fitxer
        try (Stream<String> stream_linies = Files.lines(ruta, StandardCharsets.UTF_8)) {
            // Filtrem l'stream amb les cadenes en blanc i les comptem
            long buides = stream_linies.filter(String::isBlank).count();
            // Mostrem el número de línies en blanc
            System.out.println("Línies buides: " + buides);
        }
    }


    /**
     * Activitat de l'apartat 2: copia les línies no buides, numerades.
     */
    public static int copiaLiniesNoBuides(Path origen, Path destinacio) {
        Path origenNormalitzat = origen.toAbsolutePath().normalize();
        Path destinacioNormalitzada = destinacio.toAbsolutePath().normalize();

        if (origenNormalitzat.equals(destinacioNormalitzada)) {
            System.err.println("L'origen i la destinació no poden ser el mateix fitxer.");
            return 0;
        }

        int numero = 0;
        try (BufferedReader lector = Files.newBufferedReader(origenNormalitzat, StandardCharsets.UTF_8);
             BufferedWriter escriptor = Files.newBufferedWriter(
                     destinacioNormalitzada,
                     StandardCharsets.UTF_8,
                     StandardOpenOption.CREATE,
                     StandardOpenOption.TRUNCATE_EXISTING)) {

            String linia;
            while ((linia = lector.readLine()) != null) {
                if (linia.isBlank()) {
                    continue;
                }

                numero++;
                escriptor.write(numero + ". " + linia);
                escriptor.newLine();
            }

            System.out.printf("S'han copiat %d línies en %s.%n", numero, destinacioNormalitzada);
        } catch (InvalidPathException e) {
            System.err.println("Alguna de les rutes no és vàlida.");
        } catch (NoSuchFileException e) {
            System.err.println("No s'ha trobat el fitxer: " + e.getFile());
        } catch (AccessDeniedException e) {
            System.err.println("No tenim permisos per accedir a: " + e.getFile());
        } catch (IOException e) {
            System.err.println("No s'ha pogut completar la còpia: " + e.getMessage());
        }
        return numero;
    }
}
